INSERT INTO CDM.VT_C_COM_CD
SELECT * FROM (
  SELECT * FROM CDM.ST_C_COM_CD T
  EXCEPT ALL
  SELECT * FROM CDM.C_COM_CD F WHERE F.end_dt = DATE '{MAX_DATE}'
) T01;

